-- Casco Notary Services CMS (admin: /admin/cns)
-- Run this once in the Supabase SQL editor. Safe to re-run: the tables are
-- created if missing and the initial content is only inserted when empty.
-- Public pages keep working from messages/*.json until this has been run.

create extension if not exists pgcrypto;

-- One row per (text, language): home.h1 / en, home.h1 / es, …
create table if not exists cns_texts (
  key text not null,
  locale text not null check (locale in ('en', 'es')),
  value text not null default '',
  updated_at timestamptz not null default now(),
  primary key (key, locale)
);

-- Every list of the site: services, prices, FAQ, steps, … (see collection).
-- title/body hold what the components call title/description,
-- label/price or question/answer depending on the collection.
create table if not exists cns_items (
  id uuid primary key default gen_random_uuid(),
  collection text not null check (collection in ('trust', 'crossSell', 'services', 'remote', 'prices', 'steps', 'faq')),
  sort_order int not null default 0,
  active boolean not null default true,
  title_en text not null default '',
  title_es text not null default '',
  body_en text not null default '',
  body_es text not null default '',
  updated_at timestamptz not null default now()
);
create index if not exists cns_items_collection_sort_idx on cns_items (collection, sort_order);

alter table cns_texts enable row level security;
alter table cns_items enable row level security;

-- The public site reads with the anon key; only logged-in admins can write.
drop policy if exists "cns_texts public read" on cns_texts;
create policy "cns_texts public read" on cns_texts for select to anon, authenticated using (true);
drop policy if exists "cns_texts admin write" on cns_texts;
create policy "cns_texts admin write" on cns_texts for all to authenticated using (true) with check (true);

drop policy if exists "cns_items public read" on cns_items;
create policy "cns_items public read" on cns_items for select to anon using (active);
drop policy if exists "cns_items admin all" on cns_items;
create policy "cns_items admin all" on cns_items for all to authenticated using (true) with check (true);

-- Initial content = what the site shows today.
on conflict (key, locale) do nothing;

