  ($cns$delivery.restriction$cns$, 'en', $cns$We do not deliver across bridges or via the city's expressways (corredores).$cns$),
  ($cns$delivery.restriction$cns$, 'es', $cns$No se realizan entregas cruzando puentes ni se utilizan los corredores.$cns$),
  ($cns$delivery.location.heading$cns$, 'en', $cns$Our location$cns$),
